    const received: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's-1',
        userId: 'u1',
        updatedAt: '2026-09-30T09:00:00.000Z',
        entryCount: 2,
        title: 'First question',
      },
