      listFor: async (userId: string | number, options?: SessionListOptions) => {
        received.push({userId, options});
        return summaries;
      },
    } as unknown as SessionStore;
    const throwingStore = {
      listFor: async () => {
        throw new Error('store unavailable');
      },
